def make(path, chromsizes, binsize, balanced=False, density=1.0):
    if os.path.exists(path): os.remove(path)
    bins = cooler.binnify(pd.Series(chromsizes), binsize)
    rows=[]
    for c, grp in bins.groupby("chrom", sort=False):
        idx = grp.index.to_numpy()
        for i, b1 in enumerate(idx):
            for b2 in idx[i:]:
                if rng.random() > density: continue
                cnt = rng.poisson(100.0/(1+b2-b1)**1.1)
                if cnt: rows.append((b1,b2,cnt))
    pix = pd.DataFrame(rows, columns=["bin1_id","bin2_id","count"]) if rows else \
          pd.DataFrame({"bin1_id":[],"bin2_id":[],"count":[]}, dtype=int)
